import unittest
import subprocess
import sys

class TestCLI(unittest.TestCase):
    def run_app(self, args):
        return subprocess.run(
            [sys.executable, "-m", "temperature_converter.main"] + args,
            capture_output=True,
            text=True
        )

    def test_celsius_to_fahrenheit(self):
        result = self.run_app(["--celsius", "25"])
        self.assertEqual(result.returncode, 0)
        self.assertEqual(result.stdout.strip(), "77.0F")

    def test_fahrenheit_to_celsius(self):
        result = self.run_app(["--fahrenheit", "77"])
        self.assertEqual(result.returncode, 0)
        self.assertEqual(result.stdout.strip(), "25.0C")

    def test_invalid_input(self):
        result = self.run_app(["--celsius", "abc"])
        self.assertEqual(result.returncode, 1)
        self.assertIn("error", result.stderr)

    def test_missing_argument_value(self):
        result = self.run_app(["--celsius"])
        self.assertEqual(result.returncode, 1)
        self.assertIn("expected one argument", result.stderr)

    def test_mutual_exclusivity(self):
        result = self.run_app(["--celsius", "25", "--fahrenheit", "77"])
        self.assertEqual(result.returncode, 1)
        self.assertIn("not allowed with argument", result.stderr)

    def test_no_arguments(self):
        result = self.run_app([])
        self.assertEqual(result.returncode, 1)
        self.assertIn("usage:", result.stdout)

    def test_help(self):
        result = self.run_app(["--help"])
        self.assertEqual(result.returncode, 0)
        self.assertIn("usage:", result.stdout)

if __name__ == '__main__':
    unittest.main()

